def add_to_allowed_alarms_during_tl_preparation(additional_allowed_alarms=None):
    tl_prep_allowed_alarms = get_builtin_value('ALLOWED_ALARMS_DURING_TL_PREPARATION')
    custom_allowed_alarms = get_builtin_value('CUSTOM_ALLOWED_ALARMS')
    _add_custom_alarms(custom_allowed_alarms, tl_prep_allowed_alarms)
    _add_custom_alarms(additional_allowed_alarms, tl_prep_allowed_alarms)


def add_custom_allowed_alarms_if_defined():
    custom_allowed_alarms = get_builtin_value('CUSTOM_ALLOWED_ALARMS')
    allowed_alarms = get_builtin_value('allowed_alarms')
    _add_custom_alarms(custom_allowed_alarms, allowed_alarms)

    custom_asir_allowed_alarms = get_builtin_value('CUSTOM_ASIR_ALLOWED_ALARMS')
    asir_allowed_alarms = get_builtin_value('ASIR_ALLOWED_ALARMS')
    _add_custom_alarms(custom_asir_allowed_alarms, asir_allowed_alarms)


def get_alarms_as_list(alarms):
    """
    Ensure that alarms are returned as a list.
    :param alarms: alarms in str(json format or comma separated) or list format
    :return: list of alarms
    """
    if not isinstance(alarms, list):
        try:
            alarms = _parse_alarms_to_list(alarms)
        except ValueError:
            logging.debug(f'Cannot parse "{alarms}". Try to just split')
            alarms = alarms.split(',')
    return alarms


def _add_custom_alarms(_custom_alarms, _allowed_alarms):
    if _custom_alarms and _allowed_alarms:
        _custom_alarms = get_alarms_as_list(_custom_alarms)
        for custom_alarm in _custom_alarms:
            if custom_alarm not in _allowed_alarms:
                logging.debug(f'Adding "{custom_alarm}" to allow_alarms')
                _allowed_alarms.append(custom_alarm)


def remove_custom_allowed_alarms_if_defined():
    def remove_custom_alarms(_custom_alarms, _allowed_alarms):
        if _custom_alarms and _allowed_alarms:
            if not isinstance(_custom_alarms, list):
                try:
                    _custom_alarms = _parse_alarms_to_list(_custom_alarms)
                except ValueError:
                    logging.debug(f'Cannot parse "{_custom_alarms}". Try to just split')
                    _custom_alarms = _custom_alarms.split(',')
            for custom_alarm in _custom_alarms:
                if custom_alarm in _allowed_alarms:
                    logging.debug(f'Remove "{custom_alarm}" from allow_alarms')
                    _allowed_alarms.remove(custom_alarm)

    custom_allowed_alarms = get_builtin_value('CUSTOM_ALLOWED_ALARMS')
    allowed_alarms = get_builtin_value('allowed_alarms')
    remove_custom_alarms(custom_allowed_alarms, allowed_alarms)

    custom_asir_allowed_alarms = get_builtin_value('CUSTOM_ASIR_ALLOWED_ALARMS')
    asir_allowed_alarms = get_builtin_value('ASIR_ALLOWED_ALARMS')
    remove_custom_alarms(custom_asir_allowed_alarms, asir_allowed_alarms)


def get_default_swconfig_for_tl():
    """
    Get path to default swconfig file for testline.
    :return: str - path to default swconfig file
    """
    default_swconfig_name = 'default_swconfig.txt'
    if get_builtin_value('GEARSDIR'):
        default_swconfig_path = DefaultFileLocation.get_path_to_default_testline_file(default_swconfig_name)
    else:
        default_swconfig_path = f"commissionings/Krakow/swconfig/{default_swconfig_name}"
    return default_swconfig_path


@load_moler_configuration_from_tl()
def get_main_scout_bts_name():
    """
    Returns SCOUT BTS name.
    :return: SCOUT BTS name
    """
    testline_name = get_testline_name()
    logging.debug("TESTLINE_NAME: {}".format(testline_name))
    try:
        scout_bts_names = get_scout_bts_names_for_testline(testline=testline_name)
        logging.debug("SCOUT_BTS_NAMES: {}".format(scout_bts_names))
        scout_bts_name = scout_bts_names[0] if scout_bts_names else testline_name
        return scout_bts_name
    except Exception as e:
        logging.warning("Cannot get SCOUT BTS names from OMNIA due to: {}".format(repr(e)))
        return _get_main_scout_bts_name_when_not_defined_in_omnia(testline_name)


def _get_main_scout_bts_name_when_not_defined_in_omnia(testline_name=None):
    testline_name = testline_name or get_testline_name()
    if GenericScout().is_bts_defined_in_scout(testline_name):
        return testline_name
    else:
        scout_bts_name_multi = f"{testline_name}_1"
        if GenericScout().is_bts_defined_in_scout(scout_bts_name_multi):
            return scout_bts_name_multi


def check_if_testline_added_to_omnia_and_scout():
    """
    Check if testline is added to OMNIA and SCOUT.
    If not, log warning.
    """
    testline_name = get_testline_name()
    defined_in_omnia = False
    try:
        get_testline_details(testline_name)
        logging.info(f"Testline {testline_name} is defined in OMNIA")
        defined_in_omnia = True
    except IndexError:
        logging.warning(f"Testline {testline_name} is not defined in OMNIA. Please add it")
    except Exception as e:
        logging.warning(f"Cannot get testline details from OMNIA due to: {repr(e)}")

    if defined_in_omnia:
        scout_bts_names = get_scout_bts_names_for_testline(testline=testline_name)
        logging.info(f"Scout BTS names defined in OMNIa: {scout_bts_names}")
        if not scout_bts_names:
            logging.warning("Scout BTS link not added in OMNIA - please add it(Links tab --> Scout)")
        else:
            for scout_bts_name in scout_bts_names:
                if GenericScout().is_bts_defined_in_scout(scout_bts_name):
                    logging.info(f"{scout_bts_name} is defined in SCOUT")
                else:
                    logging.warning(f"{scout_bts_name} is not defined in SCOUT. Please add it")
    else:
        scout_bts_name = _get_main_scout_bts_name_when_not_defined_in_omnia(testline_name)
        if scout_bts_name:
            logging.info(f"{scout_bts_name} is defined in SCOUT")
        else:
            logging.warning(f"Testline {testline_name} is not defined in SCOUT. Please add it.")


def add_main_bts_metadata_to_report(bts_id=0, du_id=0, bts_type='GNB'):
    bts = GnbDuOperations() if bts_type == 'GNB' else EnbDuOperations()
    bts.connect(bts_id=bts_id, du_id=du_id)
    main_bts_name = get_main_scout_bts_name()
    bts_params = {
        'admin_connection': bts.rest_alias.format(bts_id, du_id),
        'scout_bts_name': main_bts_name
    }
    bts_metadata().add_bts_metadata_to_report(bts_params=bts_params)


def add_metadata_to_report_for_all_btss():
    def _find_scout_bts_name(bts_ip_address, bts, bts_id, all_scout_bts_params):
        if str(bts_ip_address).startswith("192.168.255"):
            logging.debug(f"LMP {bts_ip_address} address defined in config init py - check by MRBTS-ID")
            bts_info = bts.get_bts_info(bts_id)
            bts_mrbts_id = str(bts_info['mrbtsID'])
            return next(
                (param['scout_bts_name'] for param in all_scout_bts_params if
                 str(param['scout_bts_id']) == bts_mrbts_id),
                None)
        return next((param['scout_bts_name'] for param in all_scout_bts_params if
                     str(param['scout_mplane_ip']) == str(bts_ip_address)), None)

    testline_name = get_testline_name()
    omnia_not_working = False
    try:
        scout_bts_names = get_scout_bts_names_for_testline(testline=testline_name)
        logging.info(f"Scout BTS names defined in OMNIa: {scout_bts_names}")
    except Exception as e:
        logging.warning("Cannot get SCOUT BTS names from OMNIA due to: {}".format(repr(e)))
        omnia_not_working = True

    if omnia_not_working or len(scout_bts_names) <= 1:
        logging.debug("Using add_main_bts_metadata_to_report KW")
        add_main_bts_metadata_to_report()
        return

    # reporting multibts only when BTSes defined in Omnia
    all_scout_bts_params = []
    for scout_bts_name in scout_bts_names:
        scout_bts_info = GenericScout().get_bts_details(scout_bts_name)['data']
        all_scout_bts_params.append(
            {'scout_bts_name': scout_bts_name,
             'scout_bts_id': scout_bts_info['attributes']['infomodel'].get('bts_id'),
             'scout_mplane_ip': scout_bts_info['attributes']['mplane']
             })

    gnb_ids = range(len(tl_config.tl.gnbs)) if tl_config.tl.gnbs else []
    enb_ids = range(len(tl_config.tl.enbs)) if tl_config.tl.enbs else []
    all_bts_ids = {'GNB': gnb_ids, 'ENB': enb_ids}
    bts_params = []
    for bts_type in all_bts_ids:
        bts = GnbDuOperations() if bts_type == 'GNB' else EnbDuOperations()
        for bts_id in all_bts_ids[bts_type]:
            bts.connect(bts_id)
            bts_alias = bts.rest_alias.format(bts_id, 0)
            bts_ip_address = tl_config.get_web_credentials_for_du(bts_id=bts_id, bts_type=bts_type)['ip']
            scout_bts_name = _find_scout_bts_name(bts_ip_address, bts, bts_id, all_scout_bts_params)
            if scout_bts_name:
                bts_params.append({
                    'admin_connection': bts_alias,
                    'scout_bts_name': scout_bts_name
                })
    bts_metadata().add_bts_metadata_to_report(bts_params=bts_params)


@load_moler_configuration_from_tl()
def compress_moler_syslogs(compressed_file_name='moler_syslogs.tar.gz', syslog_pattern='*_SYSLOG*.log',
                           timeout=30 * 60):
    # tar -czvf moler_syslogs.tar.gz *_SYSLOG*.log --remove-files
    moler_logs_dir = get_logging_path()
    unix = DeviceFactory.get_device(name='UnixLocal')

    try:

        change_dir = unix.get_cmd(cmd_name='cd', cmd_params={
            'path': "'{}'".format(moler_logs_dir),
        })
        change_dir()

        syslog_exists = unix.get_cmd(cmd_name='ls', cmd_params={
            'path': "{}".format(syslog_pattern),
        })
        syslog_exists()

        tar_syslog = unix.get_cmd(cmd_name='tar', cmd_params={
            'options': '-czvf',
            'file': '{} {} --remove-files'.format(compressed_file_name, syslog_pattern)
        })
        tar_syslog(timeout=timeout)
    except CommandFailure:
        MolerTest.info("No moler syslog files")


def _parse_alarms_to_list(json_string):
    data = parse_json_string_to_dict(json_string)
    if isinstance(data, dict):
        return [data]
    elif isinstance(data, list):
        return data
    else:
        raise ValueError("Invalid JSON format")


def log_to_console_credentials_to_vm():
    """
    Log to console credentials to VM if CM execution.
    :return: None
    """
    if os.environ.get("CM_EXECUTION_LINK"):
        vm_fqdn = safe_call(get_vm_fqdn)
        vn_password = safe_call(get_vm_vnc_password)
        log_banner_to_console([f"VM ADDRES:\t{vm_fqdn}", f"PASSWORD:\t{vn_password}"])


def log_installed_packages():
    for dist in sorted(pkg_resources.working_set, key=lambda d: d.project_name.lower()):
        logging.info(f"{dist.project_name}=={dist.version}")


def remove_note_60002_if_exists_for_SBTS24R3():
    """
    Removes the NOTE-60002 object from the configuration if the current software version is SBTS24R3
    and the object exists in the configuration file.

    This method checks the current BTS software version and searches for the NOTE-60002 object in
    the configuration file. If the software version matches SBTS24R3 and the object is found, it
    performs a delete operation to remove the object.
    """
    du = GnbDuOperations()
    commissioning = GnbCommissioning()

    def _search_object_in_scf(scf_object='NOTE-60002'):
        scf_path = du.get_bts_configuration_file()
        with open(scf_path, 'r') as f:
            scf = f.read()
        if re.search(scf_object, scf):
            return True
        return False

    if 'SBTS24R3' in du.get_bts_sw_version():
        if _search_object_in_scf():
            logging.info('Removing NOTE-60002 object for build SBTS24R3.')
            commissioning.perform_object_recommissioning(
                dist_name='MRBTS-{}/MNL-1/NOTES-1/NOTE-60002',
                parameter=[],
                operation='delete'
            )


class CommonSetupsListener:
    ROBOT_LIBRARY_SCOPE = 'GLOBAL'
    ROBOT_LISTENER_API_VERSION = 2

    def __init__(self):
        self.ROBOT_LIBRARY_LISTENER = self
        self._test_case_statuses = {}

    def start_suite(self, suite, result):
        """
        Suite setup actions.
        :param suite: suite object
        :param result: result object
        :return: None
        """
        run_robot_keyword('setups_and_teardowns_keywords.Log To Console Credentials To Vm')
        run_robot_keyword('setups_and_teardowns_keywords.Log All Variables')
        run_robot_keyword('setups_and_teardowns_keywords.Log Installed Packages')

    def end_test(self, name, attrs):
        """
        End test actions.
        :param name: test name
        :param attrs: test attributes
        """
        self._test_case_statuses[attrs['originalname']] = attrs['status']

    def get_test_case_status(self, test_name):
        """
        Get test case status by test name.
        :param test_name: test name - original name like defined in robot file
        :return: test case status 'PASS' or 'FAIL' or None if test not found
        """
        return self._test_case_statuses.get(test_name, None)
